// Per-launch holder-staking vault (QStakeVault): deployed by anyone through the deterministic deployer with a fixed
// salt and init = creationCode ++ abi.encode(token, quote), so its address is known before the launch and a launch's
// revenue split can name it as a payee. Generated from extras.json (stakeVault); test/stake-vault.test.mjs checks it.
import {keccak_256} from '../../prototypes/qpools/client/vendor/hashes/sha3.js';
export const STAKE_DEPLOYER='0x4e59b44847b379578588920ca78fbf26c0b4956c';
export const STAKE_SALT='0x17ae31dcc40dcd63af26540496842fcb6c6ddde20d6b6429d01326cd0fa5cfbf';
export const STAKE_CREATION='';
const hex=b=>Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');
const bytes=h=>Uint8Array.from(h.replace(/^0x/,'').match(/../g),b=>parseInt(b,16));
const isAddress=x=>typeof x==='string'&&/^0x[0-9a-f]{40}$/.test(x);
/** Init code for the (token, quote) vault: what the deterministic deployer receives after the salt. */
export function stakeVaultInit(token,quote){
 if(!isAddress(token)||!isAddress(quote)||token===quote)throw new TypeError('Token and quote required');
 return STAKE_CREATION+token.slice(2).padStart(64,'0')+quote.slice(2).padStart(64,'0');
}
/** The vault's address for (token, quote), deployed or not. */
export function stakeVaultAddress(token,quote){
 const h=keccak_256(bytes(stakeVaultInit(token,quote)));
 return '0x'+hex(keccak_256(bytes('ff'+STAKE_DEPLOYER.slice(2)+STAKE_SALT.slice(2)+hex(h)))).slice(24);
}
/** Transaction data that deploys the vault (send to STAKE_DEPLOYER). */
export const stakeVaultDeployData=(token,quote)=>STAKE_SALT+stakeVaultInit(token,quote).slice(2);
